SELECT p.project_id, ROUND(AVG(e.experience_years), 2) AS average_years
FROM Project p LEFT JOIN Employee e ON p.employee_id = e.employee_id
GROUP BY p.project_id;

SELECT query_name, ROUND(AVG(rating / position), 2) AS quality,
       ROUND(100.0 * AVG(CASE WHEN rating < 3 THEN 1 ELSE 0 END), 2) AS poor_query_percentage
FROM Queries GROUP BY query_name;

)
SELECT ROUND(100.0 * AVG(CASE WHEN order_date = customer_pref_delivery_date THEN 1 ELSE 0 END), 2)
       AS immediate_percentage
FROM ranked WHERE rn = 1;

SELECT e.* FROM employees e
WHERE e.salary > (SELECT AVG(d.revenue_generated) FROM employees d
                  WHERE d.department = e.department);
